/* EventSource.url -> eventsource.EventSource_url */
static JSValue wjg_EventSource_get_url(JSContext *ctx, JSValueConst this_val)
{
    wj_obj *self = wj_this(ctx, this_val, 203);
    if (!self) { return JS_EXCEPTION; }
    int32_t n;
    WJ_FETCH_STRING(n, wr_EventSource_url(self->handle, wj_scratch.data, wj_scratch.cap));
    if (n < 0) { return wj_throw_status(ctx, n, "EventSource.url"); }
    return JS_NewStringLen(ctx, (const char *)wj_scratch.data, (size_t)n);
}

