/* HTMLElement.click() -> forms.HTMLElement_click */
static JSValue wjg_HTMLElement_click(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    wj_obj *self = wj_this(ctx, this_val, 234);
    if (!self) { return JS_EXCEPTION; }
    (void)wr_HTMLElement_click(self->handle);
    return JS_UNDEFINED;
}

