/* Performance.now() -> performance.Performance_now */
static JSValue wjg_Performance_now(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    wj_obj *self = wj_this(ctx, this_val, 345);
    if (!self) { return JS_EXCEPTION; }
    double r = wr_Performance_now();
    return JS_NewFloat64(ctx, (double)r);
}

/* Performance.timeOrigin -> performance.Performance_timeOrigin */
static JSValue wjg_Performance_get_timeOrigin(JSContext *ctx, JSValueConst this_val)
{
    wj_obj *self = wj_this(ctx, this_val, 345);
    if (!self) { return JS_EXCEPTION; }
    double r = wr_Performance_timeOrigin();
    return JS_NewFloat64(ctx, (double)r);
}

